// Demonstrating consistency model choices in a Node.js app
// Scenario: user updates profile, then immediately views their profile

// --- OPTION A: Eventual Consistency (stale read possible) ---
const dynamoDB = require('@aws-sdk/client-dynamodb');

async function updateProfileEventual(userId, name) {
  // Write to primary
  await dynamoDB.put({ TableName: 'Users', Item: { userId, name } });

  // Immediately read — might return old name from stale replica!
  const user = await dynamoDB.get({
    TableName: 'Users',
    Key: { userId },
    ConsistentRead: false  // eventual consistency (default, cheaper)
  });
  console.log(user.name); // may log OLD name — violates read-your-writes
}

// --- OPTION B: Strong Consistent Read ---
async function updateProfileStrong(userId, name) {
  await dynamoDB.put({ TableName: 'Users', Item: { userId, name } });

  // ConsistentRead: true forces read from primary — slower, costs 2x RCUs
  const user = await dynamoDB.get({
    TableName: 'Users',
    Key: { userId },
    ConsistentRead: true  // linearizable read
  });
  console.log(user.name); // guaranteed to log NEW name
}

// --- OPTION C: Read-your-writes via client-side cache ---
const localCache = new Map();

async function updateProfileRYW(userId, name) {
  await dynamoDB.put({ TableName: 'Users', Item: { userId, name } });
  localCache.set(userId, { name }); // cache write locally

  const user = localCache.get(userId) || await dynamoDB.get({ ... });
  console.log(user.name); // reads own write from cache
}

// Consistency model decision guide

// LINEARIZABILITY: use when correctness is non-negotiable
//   Examples: bank transfers, leader election, configuration (etcd/ZooKeeper)
//   Cost: every write requires quorum agreement; higher latency
//   Systems: etcd, ZooKeeper, Google Spanner, CockroachDB

// CAUSAL CONSISTENCY: use when preserving cause-effect is enough
//   Examples: social feed (replies after posts), collaborative editing
//   Cost: vector clocks or logical timestamps; moderate overhead
//   Systems: MongoDB (causally consistent sessions), CockroachDB

// READ-YOUR-WRITES: use for user-facing apps where self-consistency matters
//   Implementation: sticky sessions to primary, or token-based epoch reads
//   Example: user posts comment, immediately sees it in their own feed
//   Systems: most RDBMS with connection stickiness, Redis (single node)

// EVENTUAL CONSISTENCY: use when maximum availability > stale read risk
//   Examples: product catalog, social likes/views, DNS, CDN cache
//   Cost: application must tolerate stale reads; conflict resolution needed
//   Systems: DynamoDB, Cassandra, CouchDB, S3

// CAP theorem in practice:
//   CP (consistency + partition tolerance): etcd, HBase, ZooKeeper
//   AP (availability + partition tolerance): DynamoDB, Cassandra, CouchDB
//   CA (consistency + availability): single-node RDBMS (no partition tolerance)
